        check("nPk(7, 0) -- empty product", 1L, Permutations.nPk(7, 0));
        check("nPk(0, 0)", 1L, Permutations.nPk(0, 0));
        check("nPk(20, 10)", 670442572800L, Permutations.nPk(20, 10));
        check("nPk(20, 20) = 20!", 2432902008176640000L, Permutations.nPk(20, 20));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

